package application

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"sort"
	"strings"
	"time"

	"github.com/skillicinski/bo/internal/agent"
	"github.com/skillicinski/bo/internal/domain"
	internalerrors "github.com/skillicinski/bo/internal/errors"
)

const (
	toolReadCorpus   = "read_corpus"
	toolReadLogs     = "read_logs"
	toolReadDocument = "read_document"
	toolReadSummary  = "read_summary"
	toolWriteSummary = "write_summary"
	toolEditSummary  = "edit_summary"
)

var allSynthesisTools = []string{toolReadCorpus, toolReadLogs, toolReadDocument, toolReadSummary, toolWriteSummary, toolEditSummary}

func normalizeSynthesisTools(names []string) ([]string, error) {
	if len(names) == 0 || len(names) == 1 && names[0] == "all" {
		return append([]string{}, allSynthesisTools...), nil
	}
	known := make(map[string]bool, len(allSynthesisTools))
	for _, name := range allSynthesisTools {
		known[name] = true
	}
	seen := make(map[string]bool, len(names))
	validated := make([]string, 0, len(names))
	for _, name := range names {
		if !known[name] {
			return nil, fmt.Errorf("unknown synthesis tool: %s", name)
		}
		if seen[name] {
			return nil, fmt.Errorf("duplicate synthesis tool: %s", name)
		}
		seen[name] = true
		validated = append(validated, name)
	}
	return validated, nil
}

func synthTools(contextState *agentContext, names []string) []agent.Tool {
	objectParameters := func(properties map[string]any, required []string) map[string]any {
		return map[string]any{"type": "object", "properties": properties, "required": required, "additionalProperties": false}
	}
	execute := func(_ context.Context, call agent.ToolCall) (string, error) {
		return executeToolCall(contextState, call)
	}
	definitions := map[string]agent.Tool{
		toolReadCorpus:   {Definition: agent.ToolDefinition{Function: agent.ToolDeclaration{Name: toolReadCorpus, Description: "Read the authoritative corpus state, including raw snapshots and summaries.", Parameters: objectParameters(map[string]any{}, []string{})}}, Execute: execute},
		toolReadLogs:     {Definition: agent.ToolDefinition{Function: agent.ToolDeclaration{Name: toolReadLogs, Description: "Read paginated operation log entries for the current directory, newest first.", Parameters: objectParameters(map[string]any{"offset": map[string]any{"type": "integer", "default": 0, "minimum": 0}, "limit": map[string]any{"type": "integer", "default": 20, "minimum": 1, "maximum": 100}}, []string{})}}, Execute: execute},
		toolReadDocument: {Definition: agent.ToolDefinition{Function: agent.ToolDeclaration{Name: toolReadDocument, Description: "Read the newest raw Markdown document for one source identity. Use its exact filename.", Parameters: objectParameters(map[string]any{"filename": map[string]any{"type": "string"}}, []string{"filename"})}}, Execute: execute},
		toolReadSummary:  {Definition: agent.ToolDefinition{Function: agent.ToolDeclaration{Name: toolReadSummary, Description: "Read the existing Markdown summary for one source identity.", Parameters: objectParameters(map[string]any{"source_key": map[string]any{"type": "string"}}, []string{"source_key"})}}, Execute: execute},
		toolWriteSummary: {Definition: agent.ToolDefinition{Function: agent.ToolDeclaration{Name: toolWriteSummary, Description: "Create a Markdown summary for one source identity using its newest raw snapshot.", Parameters: objectParameters(map[string]any{"source_key": map[string]any{"type": "string"}, "markdown": map[string]any{"type": "string"}}, []string{"source_key", "markdown"})}}, Execute: execute},
		toolEditSummary:  {Definition: agent.ToolDefinition{Function: agent.ToolDeclaration{Name: toolEditSummary, Description: "Replace an existing Markdown summary for one source identity in full.", Parameters: objectParameters(map[string]any{"source_key": map[string]any{"type": "string"}, "markdown": map[string]any{"type": "string"}}, []string{"source_key", "markdown"})}}, Execute: execute},
	}
	tools := make([]agent.Tool, 0, len(names))
	for _, name := range names {
		tools = append(tools, definitions[name])
	}
	return tools
}

type agentSource struct {
	SourceKey        string
	LatestFilename   string
	LatestWrittenAt  time.Time
	LatestStateIndex int
}

type agentContext struct {
	ctx             context.Context
	directory       string
	workspace       Workspace
	options         OperationOptions
	documents       map[string]domain.DocumentRef
	sources         map[string]agentSource
	state           domain.State
	revision        Revision
	maxOutputBytes  int
	completed       map[string]bool
	written         map[string]bool
	mutationOps     map[string]Operation
	committed       []Operation
	logEvents       []Operation
	logWindowLoaded bool
	eventFailure    error
}

func (context *agentContext) nextMutationOperation(key string) Operation {
	operation, ok := context.mutationOps[key]
	if !ok {
		operation = newOperation(CommandWriteSummary, context.options.Actor)
	} else {
		operation.Attempt++
		operation.Timestamp = time.Now().UTC().Format(time.RFC3339Nano)
	}
	context.mutationOps[key] = operation
	return operation
}

func systemPrompt(context *agentContext, documentNames []string, readLogsEnabled bool) string {
	identities := make([]string, 0, len(context.sources))
	for sourceKey, source := range context.sources {
		identities = append(identities, sourceKey+" ("+source.LatestFilename+")")
	}
	sort.Strings(identities)
	logInstruction := ""
	if readLogsEnabled {
		logInstruction = " Before reading raw documents, inspect the available recent scoped operation entries, including failed attempts, with read_logs."
	}
	return fmt.Sprintf("You are bo's document-summary agent for %s. Purpose: turn each source into a concise Markdown summary that retains its key claims. Ontology: raw documents are immutable snapshots; a source identity is an exact URL or raw:filename; a summary is one mutable document derived from the newest raw snapshot; state is the authoritative record of these links. Rules: use only evidence from the source, preserve qualifications and uncertainty, attribute experience, measurements, recommendations, opinions, and forecasts to their author, and never modify raw documents or invent facts. The host owns document access, newest-snapshot selection, provenance, state publication, and completion.%s A current summary derived from the current raw filename means that source is complete; do not rewrite it. Use the available bounded tools. Source identities: %s. Latest raw documents: %s.", context.directory, logInstruction, strings.Join(identities, ", "), strings.Join(documentNames, ", "))
}

func DiscoverDocuments(ctx context.Context, workspace Workspace) (map[string]domain.DocumentRef, error) {
	refs, err := workspace.ListDocuments(ctx, domain.DocumentKindRaw)
	if err != nil {
		return nil, normalizeError(err, internalerrors.KindFilesystem, "listing raw documents")
	}
	documents := make(map[string]domain.DocumentRef, len(refs))
	for _, ref := range refs {
		if ref.Kind != domain.DocumentKindRaw {
			return nil, internalerrors.Validation("workspace returned a non-raw document")
		}
		if err := domain.ValidateDocumentName(ref.Name); err != nil {
			return nil, err
		}
		documents[ref.Name] = ref
	}
	return documents, nil
}

func sourceGroups(documents map[string]domain.DocumentRef, state domain.State) map[string]agentSource {
	stateSnapshots := make(map[string]agentSource)
	stateIndex := 0
	for _, source := range state.Sources {
		for _, snapshot := range source.Snapshots {
			stateSnapshots[snapshot.Filename] = agentSource{SourceKey: source.SourceKey, LatestWrittenAt: snapshot.WrittenAt, LatestStateIndex: stateIndex}
			stateIndex++
		}
	}
	names := make([]string, 0, len(documents))
	for name := range documents {
		names = append(names, name)
	}
	sort.Strings(names)
	sources := map[string]agentSource{}
	for _, filename := range names {
		sourceKey, writtenAt, stateIndex := "raw:"+filename, time.Time{}, 0
		if snapshot, ok := stateSnapshots[filename]; ok {
			sourceKey, writtenAt, stateIndex = snapshot.SourceKey, snapshot.LatestWrittenAt, snapshot.LatestStateIndex
		}
		current, ok := sources[sourceKey]
		if !ok || writtenAt.After(current.LatestWrittenAt) || writtenAt.Equal(current.LatestWrittenAt) && stateIndex > current.LatestStateIndex {
			sources[sourceKey] = agentSource{LatestFilename: filename, LatestWrittenAt: writtenAt, LatestStateIndex: stateIndex}
		}
	}
	return sources
}

func executeToolCall(context *agentContext, call agent.ToolCall) (output string, returnErr error) {
	name := call.Function.Name
	var mutation *Operation
	if name == toolWriteSummary || name == toolEditSummary {
		event := newOperation(CommandWriteSummary, context.options.Actor)
		mutation = &event
		defer func() {
			if returnErr == nil {
				return
			}
			failed := failedOperation(*mutation, returnErr)
			eventErr := commitOperationEvent(context.ctx, context.workspace, failed)
			if eventErr != nil {
				context.eventFailure = errors.Join(context.eventFailure, eventErr)
				return
			}
		}()
	}
	var arguments map[string]json.RawMessage
	if err := json.Unmarshal([]byte(call.Function.Arguments), &arguments); err != nil {
		return "", fmt.Errorf("%s arguments are malformed JSON: %v", name, err)
	}
	if arguments == nil {
		return "", fmt.Errorf("%s arguments must be a JSON object", name)
	}
	switch name {
	case toolReadCorpus:
		if len(arguments) != 0 {
			return "", fmt.Errorf("read_corpus arguments must be empty")
		}
		data, err := json.MarshalIndent(synthesisState(context.state, context.sources), "", "  ")
		if err != nil {
			return "", fmt.Errorf("serializing state failed: %v", err)
		}
		return agent.BoundedOutput(string(data), context.maxOutputBytes), nil
	case toolReadLogs:
		if len(arguments) > 2 {
			return "", fmt.Errorf("read_logs arguments must contain only offset and limit")
		}
		for key := range arguments {
			if key != "offset" && key != "limit" {
				return "", fmt.Errorf("read_logs arguments must contain only offset and limit")
			}
		}
		offset, err := intArgument(arguments, "offset", 0)
		if err != nil || offset < 0 {
			return "", fmt.Errorf("read_logs.offset must be a non-negative integer")
		}
		limit, err := intArgument(arguments, "limit", 20)
		if err != nil || limit < 1 || limit > MaxOperationPageLimit {
			return "", fmt.Errorf("read_logs.limit must be an integer from 1 to %d", MaxOperationPageLimit)
		}
		return readLogs(context, offset, limit)
	case toolReadDocument:
		if len(arguments) != 1 {
