	directory := "."
	switch kind {
	case domain.DocumentKindRaw:
	case domain.DocumentKindSummary, domain.DocumentKindDistillation:
		if kind == domain.DocumentKindSummary {
			directory = "summaries"
		} else {
			directory = "distillations"
		}
