import json
import tempfile
import unittest
from pathlib import Path

from summary_sidecar import pending_sources


class SidecarStateTest(unittest.TestCase):
    def test_pending_sources_keeps_stale_summary_filename(self):
        with tempfile.TemporaryDirectory() as directory:
            workspace = Path(directory)
            (workspace / "summaries").mkdir()
            (workspace / "new.md").write_text("source", encoding="utf-8")
            (workspace / "summaries" / "old.md").write_text("old", encoding="utf-8")
            state = {
                "sources": [
                    {
                        "source_key": "https://example.test/source",
                        "snapshots": [{"filename": "new.md", "written_at": "2026-08-23T00:00:01Z"}],
                        "summary": {"filename": "old.md", "derived_from": "old.md"},
                    }
                ]
            }
            pending = pending_sources(workspace, state)
            self.assertEqual(pending[0]["filename"], "old.md")
            self.assertEqual(pending[0]["derived_from"], "new.md")


if __name__ == "__main__":
    unittest.main()

