package main

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"strconv"
	"strings"
	"time"

	"github.com/skillicinski/bo/internal/application"
	"github.com/skillicinski/bo/internal/domain"
	"github.com/skillicinski/bo/internal/provider/deepseek"
	"github.com/skillicinski/bo/internal/storage/local"
)

const usage = "usage: bo-eval synth|distill <name> --tools all|name,name,..."
const sidecarUsage = "usage: bo-eval sidecar <name> --input <path>"

func main() {
	if err := run(os.Args[1:]); err != nil {
		fmt.Fprintf(os.Stderr, "bo-eval failed: %s\n", err)
		os.Exit(1)
	}
}

func run(args []string) error {
	if len(args) > 0 && args[0] == "sidecar" {
		return runSidecar(args[1:])
	}
	workflow, name, toolNames, err := parseWorkflowArgs(args)
	if err != nil {
		return err
	}
	apiKey := os.Getenv("DEEPSEEK_API_KEY")
	if apiKey == "" {
		return fmt.Errorf("DEEPSEEK_API_KEY is not set")
	}
	synthesisOptions := application.DefaultSynthesisOptions()
	if value := os.Getenv("BO_EVAL_RUNTIME_TIMEOUT_SECONDS"); value != "" {
		timeout, err := strconv.Atoi(value)
		if err != nil || timeout < 1 {
			return fmt.Errorf("BO_EVAL_RUNTIME_TIMEOUT_SECONDS must be a positive integer")
		}
		synthesisOptions.RuntimeTimeoutSeconds = timeout
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return err
	}
	workspace, err := local.NewManager(home).Open(context.Background(), name)
	if err != nil {
		return err
	}
	defer workspace.Close()
	provider := deepseek.New(apiKey, os.Getenv("DEEPSEEK_API_URL"))
	if workflow == "distill" {
		result, err := application.DistillWithTools(context.Background(), workspace, provider, synthesisOptions, toolNames, application.OperationOptions{Actor: "eval"})
		if err != nil {
			return err
		}
		if result.Skipped {
			fmt.Printf("distill skipped: %s\n", result.Reason)
		} else {
			fmt.Printf("distilled: %s\n", result.Filename)
		}
		return nil
	}
	result, err := application.SynthesizeWithTools(context.Background(), workspace, provider, synthesisOptions, toolNames, application.OperationOptions{Actor: "eval"})
	if err != nil {
		return err
	}
	fmt.Printf("%d summaries written\n", result.SummariesWritten)
	return nil
}

type sidecarPlan struct {
	Summaries []sidecarSummary `json:"summaries"`
}

type sidecarSummary struct {
	SourceKey   string `json:"source_key"`
	Filename    string `json:"filename"`
	DerivedFrom string `json:"derived_from"`
	Markdown    string `json:"markdown"`
}

func runSidecar(args []string) error {
	name, input, err := parseSidecarArgs(args)
	if err != nil {
		return err
	}
	data, err := os.ReadFile(input)
	if err != nil {
		return err
	}
	var plan sidecarPlan
	if err := json.Unmarshal(data, &plan); err != nil {
		return fmt.Errorf("parse sidecar plan: %w", err)
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return err
	}
	workspace, err := local.NewManager(home).Open(context.Background(), name)
	if err != nil {
		return err
	}
	defer workspace.Close()
	ctx := context.Background()
	written := 0
	for _, summary := range plan.Summaries {
		state, revision, err := workspace.ReadState(ctx)
		if err != nil {
			return err
		}
		source, raw, err := sidecarSource(state, summary.SourceKey)
		if err != nil {
			return err
		}
		if summary.DerivedFrom != "" && summary.DerivedFrom != raw.Filename {
			return fmt.Errorf("sidecar summary for %s is derived from %s, want %s", summary.SourceKey, summary.DerivedFrom, raw.Filename)
		}
		if strings.TrimSpace(summary.Markdown) == "" {
			return fmt.Errorf("sidecar summary for %s is empty", summary.SourceKey)
		}
		filename := summary.Filename
		createdAt := time.Now().UTC()
		if source.Summary != nil {
			filename = source.Summary.Filename
			createdAt = source.Summary.CreatedAt
		}
		if filename == "" {
			filename = raw.Filename
		}
		updatedAt := time.Now().UTC()
		if source.Summary != nil && !updatedAt.After(source.Summary.UpdatedAt) {
			updatedAt = source.Summary.UpdatedAt.Add(time.Nanosecond)
		}
		operation := application.Operation{
			OperationID: domain.NewOperationID(), Attempt: 1, Timestamp: updatedAt.Format(time.RFC3339Nano),
			Actor: "eval-python-sidecar", Command: application.CommandWriteSummary, Outcome: application.OutcomeCommitted,
			Source:   &domain.SourceIdentity{SourceKey: summary.SourceKey},
			Document: &domain.DocumentIdentity{Kind: domain.DocumentKindSummary, Filename: filename},
			Provenance: &domain.OperationProvenance{
				DerivedFrom:  &domain.DocumentIdentity{Kind: domain.DocumentKindRaw, Filename: raw.Filename},
				RawWrittenAt: &raw.WrittenAt,
			},
		}
		if _, _, err := workspace.CommitSummary(ctx, application.SummaryCommit{
			SourceKey: summary.SourceKey, Filename: filename, DerivedFrom: raw.Filename,
			RawWrittenAt: raw.WrittenAt, CreatedAt: createdAt, UpdatedAt: updatedAt,
			Contents: []byte(summary.Markdown), Event: operation,
		}, revision); err != nil {
			return err
		}
		written++
	}
	fmt.Printf("%d summaries written\n", written)
	return nil
}

func parseSidecarArgs(args []string) (string, string, error) {
	if len(args) != 3 || args[0] == "" || args[1] != "--input" || args[2] == "" {
		return "", "", fmt.Errorf("%s", sidecarUsage)
	}
	return args[0], args[2], nil
}

func sidecarSource(state domain.State, sourceKey string) (domain.SourceRecord, domain.RawRecord, error) {
	if sourceKey == "" {
		return domain.SourceRecord{}, domain.RawRecord{}, fmt.Errorf("sidecar source_key is empty")
	}
	for _, source := range state.Sources {
		if source.SourceKey != sourceKey {
			continue
		}
		if len(source.Snapshots) == 0 {
			return domain.SourceRecord{}, domain.RawRecord{}, fmt.Errorf("source has no snapshots: %s", sourceKey)
		}
		raw := source.Snapshots[0]
		for index := 1; index < len(source.Snapshots); index++ {
			candidate := source.Snapshots[index]
			if candidate.WrittenAt.After(raw.WrittenAt) || candidate.WrittenAt.Equal(raw.WrittenAt) {
				raw = candidate
			}
		}
		return source, raw, nil
	}
	return domain.SourceRecord{}, domain.RawRecord{}, fmt.Errorf("unknown sidecar source: %s", sourceKey)
}

func parseArgs(args []string) (string, []string, error) {
	workflow, name, tools, err := parseWorkflowArgs(args)
	if err != nil || workflow != "synth" {
		return "", nil, fmt.Errorf("%s", usage)
	}
	return name, tools, nil
}

func parseWorkflowArgs(args []string) (string, string, []string, error) {
	if len(args) < 3 || (args[0] != "synth" && args[0] != "distill") || args[1] == "" {
		return "", "", nil, fmt.Errorf("%s", usage)
	}
	var toolset string
	for index := 2; index < len(args); index++ {
		if args[index] != "--tools" || toolset != "" || index+1 >= len(args) {
			return "", "", nil, fmt.Errorf("%s", usage)
		}
		toolset = args[index+1]
		index++
	}
	if toolset == "" {
		return "", "", nil, fmt.Errorf("%s", usage)
	}
	if toolset == "all" {
		return args[0], args[1], nil, nil
	}
	return args[0], args[1], strings.Split(toolset, ","), nil
}
