sources=$(awk 'NF && $1 !~ /^#/ { sub(/^[[:space:]]+/, ""); sub(/[[:space:]]+$/, ""); print }' "$corpus")
[ -n "$sources" ] || { printf 'corpus has no sources: %s\n' "$corpus" >&2; exit 2; }
