    snapshots = source.get("snapshots")
    if not isinstance(snapshots, list) or not snapshots:
        raise ValueError("source snapshots must be a non-empty array")
    latest: tuple[datetime, int, str] | None = None
    for index, snapshot in enumerate(snapshots):
        if not isinstance(snapshot, dict):
            raise ValueError("source snapshot must be an object")
        filename = safe_name(snapshot.get("filename"), "snapshot filename")
        written_at = parse_timestamp(snapshot.get("written_at"))
        candidate = (written_at, index, filename)
        if latest is None or candidate[:2] > latest[:2]:
            latest = candidate
    assert latest is not None
    return latest[2], latest[0]


def pending_sources(workspace: Path, state: dict[str, Any]) -> list[dict[str, Any]]:
    sources = state.get("sources")
    if not isinstance(sources, list):
        raise ValueError("state sources must be an array")
    pending: list[dict[str, Any]] = []
    for source in sources:
        if not isinstance(source, dict):
            raise ValueError("source record must be an object")
        source_key = source.get("source_key")
        if not isinstance(source_key, str) or not source_key:
            raise ValueError("source_key must be a non-empty string")
        raw_filename, raw_written_at = latest_snapshot(source)
        raw_path = workspace / raw_filename
        if raw_path.is_symlink() or not raw_path.is_file():
            raise ValueError(f"missing raw document: {raw_filename}")
        summary = source.get("summary")
        if isinstance(summary, dict) and summary.get("derived_from") == raw_filename:
            summary_filename = safe_name(summary.get("filename"), "summary filename")
            summary_path = workspace / "summaries" / summary_filename
            if not summary_path.is_symlink() and summary_path.is_file() and summary_path.stat().st_size:
                continue
        elif summary is not None and not isinstance(summary, dict):
            raise ValueError("summary record must be an object")
        pending.append(
            {
                "source_key": source_key,
                "filename": safe_name(summary.get("filename"), "summary filename")
                if isinstance(summary, dict) and summary.get("filename")
                else raw_filename,
                "derived_from": raw_filename,
                "raw_written_at": raw_written_at.isoformat(),
                "raw_path": raw_path,
            }
        )
    pending.sort(key=lambda item: item["source_key"])
    return pending


class TransformersSummarizer(GPTSummarizer):
    """Use Scikit-LLM's estimator API with a local Transformers pipeline."""

    def __init__(self, summarizer: Any, model: str, max_words: int, max_input_tokens: int, max_new_tokens: int) -> None:
        super().__init__(model=model, max_words=max_words)
        self._summarizer = summarizer
        self._max_input_tokens = max_input_tokens
        self._max_new_tokens = max_new_tokens

    def _get_prompt(self, x: str) -> dict[str, str]:
        prompt = super()._get_prompt(x)
        # DistilBART is trained on article text, not instruction prompts. Keep
        # Scikit-LLM's transformer interface and settings, but pass the source
        # text directly to the Hugging Face model.
        prompt["messages"] = str(x)
        return prompt

    def _get_chat_completion(self, model: str, messages: str, **_: Any) -> Any:
        tokenizer = self._summarizer.tokenizer
        encoded = tokenizer(messages, truncation=True, max_length=self._max_input_tokens)
        text = tokenizer.decode(encoded["input_ids"], skip_special_tokens=True)
        return self._summarizer(text, max_new_tokens=self._max_new_tokens, do_sample=False)

    def _convert_completion_to_str(self, completion: Any) -> str:
        if isinstance(completion, list) and completion and isinstance(completion[0], dict):
            return str(completion[0].get("summary_text", ""))
        return str(completion)


def build_summarizer(model_name: str, max_words: int, max_input_tokens: int, max_new_tokens: int) -> TransformersSummarizer:
    device_name = os.environ.get("BO_SUMMARY_DEVICE", "auto")
    if device_name == "auto":
        device: Any = "mps" if torch.backends.mps.is_available() else -1
    elif device_name in {"cpu", "-1"}:
        device = -1
    else:
        device = device_name
    model = pipeline("summarization", model=model_name, device=device)
    return TransformersSummarizer(model, model_name, max_words, max_input_tokens, max_new_tokens)


def clean_summary(value: str) -> str:
    summary = value.strip().replace("```", "")
    if summary.lower().startswith("summarized text:"):
        summary = summary.split(":", 1)[1].strip()
    if not summary:
        raise ValueError("model returned an empty summary")
    return summary + "\n"


def generate(workspace: Path, output: Path, model_name: str, max_words: int, max_input_tokens: int, max_new_tokens: int) -> int:
    state_path = workspace / "state.json"
    state = json.loads(state_path.read_text(encoding="utf-8"))
    pending = pending_sources(workspace, state)
    if pending:
        summarizer = build_summarizer(model_name, max_words, max_input_tokens, max_new_tokens)
        texts = [item["raw_path"].read_text(encoding="utf-8") for item in pending]
        generated = summarizer.fit_transform(texts)
        for item, summary in zip(pending, generated):
            item["markdown"] = clean_summary(str(summary))
            del item["raw_path"]
    payload = {"model": model_name, "summaries": pending}
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(json.dumps(payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(f"python summary sidecar: {len(pending)} summaries ({model_name})")
    return len(pending)


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--workspace", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--model", default=os.environ.get("BO_SUMMARY_MODEL", DEFAULT_MODEL))
    parser.add_argument("--max-words", type=int, default=int(os.environ.get("BO_SUMMARY_MAX_WORDS", "100")))
    parser.add_argument("--max-input-tokens", type=int, default=int(os.environ.get("BO_SUMMARY_MAX_INPUT_TOKENS", "1024")))
    parser.add_argument("--max-new-tokens", type=int, default=int(os.environ.get("BO_SUMMARY_MAX_NEW_TOKENS", "128")))
    args = parser.parse_args(argv)
    if args.max_words < 1 or args.max_input_tokens < 1 or args.max_new_tokens < 1:
        parser.error("summary limits must be positive")
    try:
        generate(args.workspace, args.output, args.model, args.max_words, args.max_input_tokens, args.max_new_tokens)
    except (OSError, ValueError, json.JSONDecodeError) as error:
        print(f"python summary sidecar failed: {error}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
#!/bin/sh
set -eu

script_dir=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
python=${BO_SUMMARY_SIDECAR_PYTHON:-python3}
exec "$python" "$script_dir/summary_sidecar.py" "$@"
# Experimental Python summary sidecar

This sidecar is opt-in. It reads a bo workspace, summarizes raw Markdown with
Scikit-LLM's text-to-text estimator API backed by a Transformers pipeline, and
writes a JSON commit plan. The eval runner uses the existing Go workspace
adapter to commit that plan. Distillation remains on the Go/DeepSeek path.

The default model is `sshleifer/distilbart-cnn-12-6`.

```bash
python3 -m venv /tmp/bo-python-summary-sidecar-venv
/tmp/bo-python-summary-sidecar-venv/bin/python -m pip install -r experiments/python-summary-sidecar/requirements.txt
export BO_SUMMARY_SIDECAR_PYTHON=/tmp/bo-python-summary-sidecar-venv/bin/python
export BO_SUMMARY_SIDECAR="$PWD/experiments/python-summary-sidecar/run.sh"
DEEPSEEK_API_KEY=... mise run evals
```

The sidecar does not write workspace state or documents directly. Its output
is temporary eval data and can be removed after the run.

